/*! @praetor/app-bridge vendored ESM — AUTO-GENERATED from src/core.js. Do not edit by hand. */
/**
 * @praetor/app-bridge — framework-agnostic core.
 *
 * `createBridge()` returns one bridge instance with every public method
 * as a closure (no `this`, so the returned fns can be freely detached
 * and re-exported). Two consumers wrap it:
 *
 *   • src/index.js          — ESM facade, re-exports the named fns
 *                             (`import { praetor } from '@praetor/app-bridge'`).
 *   • dist/app-bridge.global.js — IIFE generated by
 *                             scripts/build-global.mjs that calls
 *                             createBridge() once and assigns the result
 *                             to `window.praetor`, so a plain HTML file
 *                             can `<script src>` it (or inline it) with
 *                             NO bundler, NO npm install, NO framework.
 *
 * Wire format: every message is a BridgeEnvelope. The host accepts
 * frames tagged `source: 'praetor-app'`; host→app frames carry
 * `source: 'praetor-host'`. See src/protocol.ts.
 *
 * Sandboxed-artifact bootstrap. When the SDK runs inside a strictly
 * sandboxed iframe (`sandbox="allow-scripts"`, e.g. an agent-generated
 * artifact HTML rendered from a blob: URL or srcDoc), the iframe has a
 * unique opaque origin and CANNOT read the parent's origin. postMessage
 * still needs a concrete `targetOrigin` for any frame carrying data
 * (never '*', or a co-embedding attacker page could capture it). The
 * bootstrap solves the chicken-and-egg:
 *   1. init() emits a payload-free `app.ready` HANDSHAKE to '*' — safe,
 *      it carries no user data, only signals "an app is here".
 *   2. The host learns our window via `event.source` and replies with a
 *      `praetor-host` frame; the SDK reads the parent's real origin off
 *      `event.origin` and pins it as the trusted host origin.
 *   3. Any data frame (chat.send/...) emitted before step 2 is QUEUED in
 *      an outbox and flushed to the now-known origin — never to '*'.
 * In the classic bound-app case the origin is usually known immediately
 * from `document.referrer`, so the queue stays empty and behaviour is
 * identical to the pre-bootstrap SDK.
 *
 * Zero dependencies.
 */
const COMPANION_PROTOCOL = 1;
const COMPANION_SOURCE = 'praetor-companion-host';
const COMPANION_IFRAME_SOURCE = 'praetor-companion-frame';

function randomId(prefix) {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return `${prefix}-${crypto.randomUUID()}`;
  }
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2)}`;
}

/**
 * Embed Praetor's User-End companion chat in a host-owned DOM container.
 * This is deliberately separate from the iframe-side singleton state below:
 * every call owns exactly one iframe, listener and server-side thread.
 */
export async function createChat(options) {
  const opts = options || {};
  const container = opts.container;
  if (!container || typeof container.appendChild !== 'function') {
    throw new TypeError('praetor.createChat: container must be a DOM element');
  }
  if (!opts.appId || !String(opts.appId).trim()) {
    throw new TypeError('praetor.createChat: appId is required');
  }

  let auth = opts.auth || { type: 'app-portal-sdk' };
  if (!['app-portal-token', 'app-portal-sdk', 'token-provider'].includes(auth.type)) {
    throw new TypeError(`praetor.createChat: unsupported auth type ${String(auth.type)}`);
  }
  if (auth.type === 'app-portal-token' && !auth.token) {
    if (auth.fallbackToSdk === false) {
      throw new TypeError('praetor.createChat: app-portal-token requires token when fallbackToSdk is false');
    }
    auth = { type: 'app-portal-sdk' };
  }
  if (auth.type === 'app-portal-sdk' && auth.token) {
    throw new TypeError('praetor.createChat: app-portal-sdk does not accept token');
  }
  if (auth.type === 'token-provider' && typeof auth.getToken !== 'function') {
    throw new TypeError('praetor.createChat: token-provider requires getToken()');
  }

  const instanceId = randomId('copilot');
  const base = opts.praetorUrl || '/copilot-chat';
  const url = new URL(base, typeof window !== 'undefined' ? window.location.href : undefined);
  const targetOrigin = url.origin;
  url.searchParams.set('embed', '1');
  url.searchParams.set('appId', String(opts.appId));
  url.searchParams.set('instanceId', instanceId);

  const iframe = document.createElement('iframe');
  iframe.src = url.toString();
  iframe.title = opts.title || 'Praetor companion chat';
  iframe.setAttribute('data-praetor-companion', instanceId);
  iframe.setAttribute('allow', 'clipboard-write');
  // Chromium's credentialless iframe gives Companion an ephemeral network
  // context: an existing Praetor login/refresh cookie in the embedding browser
  // is not inherited. CopilotChat also sends every fetch with credentials=omit
  // for browsers that do not implement this attribute yet.
  iframe.setAttribute('credentialless', '');
  iframe.style.width = (opts.style && opts.style.width) || '100%';
  iframe.style.height = (opts.style && opts.style.height) || '100%';
  iframe.style.border = '0';
  if (opts.style && opts.style.className) iframe.className = opts.style.className;

  let status = 'creating';
  let destroyed = false;
  let threadId;
  let finalFeatures;
  let chatReady = false;
  const pendingPrompts = [];
  const pendingRequests = new Map();
  const listeners = new Map();
  let sessionTimer;

  function timeoutError() {
    const error = new Error('TIMEOUT');
    error.code = 'TIMEOUT';
    return error;
  }

  function rejectPending(error) {
    for (const pending of pendingPrompts) pending.reject(error);
    pendingPrompts.splice(0);
    for (const pending of pendingRequests.values()) {
      clearTimeout(pending.timer);
      pending.reject(error);
    }
    pendingRequests.clear();
  }

  function postPrompt(item) {
    framePost('copilot.prompt.send', { prompt: item.prompt }, item.requestId);
    item.timer = setTimeout(() => {
      pendingRequests.delete(item.requestId);
      item.reject(timeoutError());
    }, 10_000);
    pendingRequests.set(item.requestId, item);
  }

  function emit(type, payload) {
    const handlers = listeners.get(type);
    if (!handlers) return;
    for (const handler of [...handlers]) handler(payload);
  }

  function framePost(type, payload, requestId) {
    if (destroyed || !iframe.contentWindow) return;
    iframe.contentWindow.postMessage({
      source: COMPANION_SOURCE,
      protocol: COMPANION_PROTOCOL,
      instanceId,
      type,
      ...(requestId ? { requestId } : {}),
      ...(payload === undefined ? {} : { payload }),
    }, targetOrigin);
  }

  async function tokenForHandshake() {
    if (auth.type === 'app-portal-token') return auth.token;
    if (auth.type === 'token-provider') return Promise.race([
      Promise.resolve().then(() => auth.getToken()),
      new Promise((_, reject) => setTimeout(() => reject(timeoutError()), 10_000)),
    ]);
    return undefined; // iframe uses its App Portal SDK adapter.
  }

  async function onMessage(event) {
    if (destroyed || event.origin !== targetOrigin || event.source !== iframe.contentWindow) return;
    const env = event.data;
    if (!env || env.source !== COMPANION_IFRAME_SOURCE || env.protocol !== COMPANION_PROTOCOL || env.instanceId !== instanceId) return;

    if (env.type === 'copilot.ready') {
      clearTimeout(readyTimer);
      status = 'authenticating';
      try {
        const token = await tokenForHandshake();
        if (destroyed) return;
        framePost('copilot.auth', {
          appId: String(opts.appId),
          auth: { type: auth.type, ...(token ? { token } : {}) },
          context: opts.context || opts.params,
          hostOrigin: window.location.origin,
        });
        sessionTimer = setTimeout(() => {
          if (status !== 'ready' && !destroyed) {
            status = 'error';
            rejectPending(timeoutError());
            emit('copilot.error', { code: 'TIMEOUT' });
          }
        }, 15_000);
      } catch (error) {
        status = 'auth-required';
        rejectPending(error);
        emit('authRequired', { code: 'TOKEN_UNAVAILABLE' });
      }
      return;
    }

    if (env.type === 'copilot.authenticated' || env.type === 'copilot.session.created') {
      clearTimeout(sessionTimer);
      status = 'ready';
      threadId = env.payload?.threadId || threadId;
      finalFeatures = env.payload?.features || finalFeatures;
    } else if (env.type === 'copilot.chat.ready') {
      chatReady = true;
      for (const item of pendingPrompts.splice(0)) postPrompt(item);
    } else if (env.type === 'copilot.prompt.accepted' || env.type === 'copilot.prompt.rejected'
      || env.type === 'copilot.context.updated' || env.type === 'copilot.context.rejected') {
      const pending = pendingRequests.get(env.requestId);
      if (!pending) return;
      clearTimeout(pending.timer);
      pendingRequests.delete(env.requestId);
      if (env.type === 'copilot.prompt.accepted' || env.type === 'copilot.context.updated') pending.resolve(env.payload);
      else pending.reject(new Error(env.payload?.code || 'PROMPT_REJECTED'));
    } else if (env.type === 'copilot.auth.required') {
      status = 'auth-required';
      rejectPending(new Error(env.payload?.code || 'AUTH_REQUIRED'));
      emit('authRequired', env.payload);
    } else if (env.type === 'copilot.error') {
      status = 'error';
      rejectPending(new Error(env.payload?.code || 'COPILOT_ERROR'));
    }
    emit(env.type, env.payload);
  }

  window.addEventListener('message', onMessage);
  container.appendChild(iframe);
  const readyTimer = setTimeout(() => {
    if (status === 'creating' && !destroyed) {
      status = 'error';
      rejectPending(timeoutError());
      emit('copilot.error', { code: 'TIMEOUT' });
    }
  }, 10_000);

  const api = {
    open() {
      if (destroyed) throw new Error('praetor.createChat: instance destroyed');
      iframe.style.display = '';
    },
    close() {
      if (destroyed) throw new Error('praetor.createChat: instance destroyed');
      iframe.style.display = 'none';
    },
    toggle() {
      if (destroyed) throw new Error('praetor.createChat: instance destroyed');
      if (iframe.style.display === 'none') api.open(); else api.close();
    },
    isOpen() { return !destroyed && iframe.style.display !== 'none'; },
    focus() {
      if (destroyed) throw new Error('praetor.createChat: instance destroyed');
      api.open();
      framePost('copilot.focus');
    },
    send(prompt) {
      if (destroyed) return Promise.reject(new Error('praetor.createChat: instance destroyed'));
      if (!prompt || !String(prompt).trim()) return Promise.reject(new TypeError('praetor.createChat: prompt is required'));
      return new Promise((resolve, reject) => {
        const item = { prompt: String(prompt), requestId: randomId('request'), resolve, reject, timer: undefined };
        if (chatReady) postPrompt(item);
        else pendingPrompts.push(item);
      });
    },
    setContext(context) {
      if (destroyed) return Promise.reject(new Error('praetor.createChat: instance destroyed'));
      return new Promise((resolve, reject) => {
        const requestId = randomId('context');
        const timer = setTimeout(() => {
          pendingRequests.delete(requestId);
          reject(timeoutError());
        }, 10_000);
        pendingRequests.set(requestId, { resolve, reject, timer });
        framePost('copilot.context.update', { context }, requestId);
      });
    },
    getState() { return { status, ...(threadId ? { threadId } : {}), ...(finalFeatures ? { features: finalFeatures } : {}) }; },
    on(type, handler) {
      if (typeof handler !== 'function') throw new TypeError('praetor.createChat: event handler must be a function');
      const handlers = listeners.get(type) || new Set();
      handlers.add(handler);
      listeners.set(type, handlers);
      return () => handlers.delete(handler);
    },
    destroy() {
      if (destroyed) return;
      framePost('copilot.destroy');
      destroyed = true;
      status = 'destroyed';
      clearTimeout(readyTimer);
      clearTimeout(sessionTimer);
      rejectPending(new Error('praetor.createChat: instance destroyed'));
      window.removeEventListener('message', onMessage);
      listeners.clear();
      iframe.remove();
    },
  };
  return api;
}

export function createBridge() {
  const PROTOCOL = 1;
  const APP_SOURCE = 'praetor-app';
  const HOST_SOURCE = 'praetor-host';

  const state = {
    appId: null,
    ready: false,
    // Trusted parent origin learned from `init({ hostOrigin })`,
    // `document.referrer`, or the first inbound host frame. ALL data
    // frames are scoped to this origin (never '*').
    hostOrigin: null,
    commandHandlers: new Map(), // type → (payload) => Promise<unknown> | unknown
    pendingRequests: new Map(), // requestId → { resolve, reject, timer }
    outbox: [], // data frames queued until hostOrigin is known
    listener: null,
    requestSeq: 0,
  };

  /**
   * Initialise the bridge. Call once per app instance.
   *
   * @param {{ appId?: string, hostOrigin?: string }} [options]
   *   - `appId`: optional. Bound apps pass the `apps[].id` from the
   *     workspace spec so the Portal can route multi-app commands.
   *     Artifact HTML can omit it — the host routes artifacts by iframe
   *     identity (`event.source`), not by id.
   *   - `hostOrigin`: optional explicit Portal origin (e.g.
   *     'https://praetor.example.com'). When omitted, learned from
   *     `document.referrer` and/or the first inbound host frame.
   */
  function init(options) {
    const opts = options || {};
    state.appId = opts.appId || null;

    if (opts.hostOrigin) {
      state.hostOrigin = opts.hostOrigin;
    } else if (!state.hostOrigin && typeof document !== 'undefined' && document.referrer) {
      try {
        state.hostOrigin = new URL(document.referrer).origin;
      } catch {
        // Leave the origin unset until the first valid host frame.
      }
    }

    if (typeof window !== 'undefined') {
      if (state.listener) window.removeEventListener('message', state.listener);
      state.listener = (event) => handleHostMessage(event);
      window.addEventListener('message', state.listener);
    }

    state.ready = true;
    // Announce readiness. If the origin is already known this goes
    // straight to the host; otherwise it's a payload-free handshake to
    // '*' so a null-origin sandboxed iframe can still bootstrap.
    post({ type: 'app.ready' }, { handshake: true });
  }

  /** Submit a real user message to the chat (same path as typing + Enter). */
  function sendToChat(text, attachments) {
    if (!text || !String(text).trim()) return;
    post({ type: 'chat.send', payload: { text: String(text), attachments } });
  }

  /** Pre-fill the composer with `text` without auto-submitting. */
  function suggest(text) {
    if (!text) return;
    post({ type: 'chat.suggest', payload: { text: String(text) } });
  }

  /**
   * Tell the host the user just selected / focused something. The next
   * agent prompt prepends this as a hidden context fragment.
   */
  function notifyContext(ctx) {
    const c = ctx || {};
    post({ type: 'context.update', payload: { entity: c.entity, id: c.id, label: c.label, payload: c.payload } });
  }

  /** Register a workspace file / URL with the artifact registry. */
  function publishArtifact(art) {
    const a = art || {};
    if (!a.file) throw new Error('praetor.publishArtifact: file is required');
    post({ type: 'artifact.publish', payload: { title: a.title, file: a.file, type: a.type, format: a.format } });
  }

  /** Ask the host to navigate the Portal shell to a different menu / path. */
  function navIntent(intent) {
    const i = intent || {};
    post({ type: 'nav.intent', payload: { menuId: i.menuId, path: i.path } });
  }

  /**
   * Register a handler for a host→app command (P6 MCP bridge). Returns
   * value (sync or Promise) is posted back as the request response.
   * @returns {() => void} unsubscribe
   */
  function onCommand(type, handler) {
    state.commandHandlers.set(type, handler);
    return () => state.commandHandlers.delete(type);
  }

  /**
   * Send a request to the host and await a response. Rejects on timeout
   * (default 10s) or when the host origin isn't known yet.
   */
  function request(type, payload, options) {
    const opts = options || {};
    const timeoutMs = opts.timeoutMs == null ? 10000 : opts.timeoutMs;
    return new Promise((resolve, reject) => {
      if (!state.hostOrigin) {
        reject(new Error('praetor.request: host origin not yet known'));
        return;
      }
      const requestId = nextRequestId();
      const timer = setTimeout(() => {
        state.pendingRequests.delete(requestId);
        reject(new Error(`praetor.request: timeout(${type})`));
      }, timeoutMs);
      state.pendingRequests.set(requestId, { resolve, reject, timer });
      post({ type, requestId, payload });
    });
  }

  /**
   * Tear down the bridge: remove the window message listener, reject
   * any in-flight requests, and clear queued frames. Call when the app
   * unmounts (SPA route change / iframe teardown) so a stale listener
   * doesn't keep responding to host commands on a dead instance.
   */
  function destroy() {
    if (typeof window !== 'undefined' && state.listener) {
      window.removeEventListener('message', state.listener);
    }
    state.listener = null;
    state.ready = false;
    for (const pending of state.pendingRequests.values()) {
      clearTimeout(pending.timer);
      pending.reject(new Error('praetor: bridge destroyed'));
    }
    state.pendingRequests.clear();
    state.outbox.length = 0;
  }

  function nextRequestId() {
    if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
      return `req-${crypto.randomUUID()}`;
    }
    state.requestSeq += 1;
    return `req-${Date.now()}-${state.requestSeq}`;
  }

  // ---- Internals --------------------------------------------------------

  /**
   * @param {object} envelope — partial frame ({ type, payload?, requestId? }).
   * @param {{ handshake?: boolean }} [opts] — when the origin is unknown
   *   and `handshake` is set, broadcast to '*' (payload-free frames only).
   *   Data frames without `handshake` are queued in the outbox instead.
   */
  function post(envelope, opts) {
    if (typeof window === 'undefined' || window.parent === window) return;
    const frame = {
      source: APP_SOURCE,
      protocol: PROTOCOL,
      ...(state.appId ? { appId: state.appId } : {}),
      ...envelope,
    };
    if (state.hostOrigin) {
      window.parent.postMessage(frame, state.hostOrigin);
      return;
    }
    // Origin not known yet.
    if (opts && opts.handshake) {
      // SECURITY: only ever broadcast payload-free handshake frames.
      // app.ready carries no user data — it just lets the host learn
      // our window so it can reply with its origin.
      window.parent.postMessage(frame, '*');
      return;
    }
    // Data frame: queue and flush once we learn the trusted origin.
    state.outbox.push(envelope);
  }

  function flushOutbox() {
    if (!state.hostOrigin) return;
    const items = state.outbox.splice(0, state.outbox.length);
    for (const env of items) post(env);
  }

  async function handleHostMessage(event) {
    const env = event.data;
    if (!env || env.source !== HOST_SOURCE || env.protocol !== PROTOCOL) return;
    if (env.appId && state.appId && env.appId !== state.appId) return;

    // First valid host frame teaches us the trusted parent origin
    // (covers sandboxed artifacts where document.referrer is blank).
    // Subsequent frames MUST match the learned origin so a second
    // window can't hijack the outbound channel.
    if (!state.hostOrigin) {
      state.hostOrigin = event.origin;
      flushOutbox();
    } else if (event.origin !== state.hostOrigin) {
      return;
    }

    // A bare handshake reply (host.hello) just teaches origin — nothing
    // else to do.
    if (env.type === 'host.hello') return;

    // Response to a request we initiated.
    if (env.type === 'response' && env.requestId) {
      const pending = state.pendingRequests.get(env.requestId);
      if (pending) {
        clearTimeout(pending.timer);
        state.pendingRequests.delete(env.requestId);
        pending.resolve(env.payload);
      }
      return;
    }

    // Command from the host — dispatch to a registered handler.
    const handler = state.commandHandlers.get(env.type);
    const requestId = env.requestId;
    if (!handler) {
      if (requestId) post({ type: 'response', requestId, payload: { ok: false, error: `no handler for ${env.type}` } });
      return;
    }
    try {
      const result = await handler(env.payload);
      if (requestId) post({ type: 'response', requestId, payload: { ok: true, result } });
    } catch (err) {
      const message = err && err.message ? err.message : String(err);
      if (requestId) post({ type: 'response', requestId, payload: { ok: false, error: message } });
    }
  }

  /**
   * Ask the host for the CURRENT VIEWER's delegated App Portal (EnOS) upstream
   * token, so this app can call an upstream API as the signed-in user. Resolves
   * to the token string, or `null` when delegation is off, the viewer is not an
   * App Portal SSO session, or this is local dev / preview (no host). Absence is
   * normal — a transport error also resolves to `null`, so callers only ever
   * branch on `token` vs `null`, never a throw.
   *
   * Security: do NOT cache the result — request it per call. It is short-lived
   * and revalidated upstream. Do not persist it or log it. See the
   * `app-portal-integration` skill.
   */
  function getAppPortalToken(options) {
    return request('getAppPortalToken', undefined, options)
      .then((payload) => (payload && typeof payload.token === 'string' ? payload.token : null))
      .catch(() => null);
  }

  /**
   * Ask the host who is viewing the app: the signed-in Praetor user's
   * `{ id, name }`, or `null` when nobody is (an anonymous viewer of a
   * public app), the host predates this request (it times out), or the
   * transport fails. Never throws for absence. Identity only — never a
   * token: an app that needs to act AS the viewer upstream uses
   * `getAppPortalToken()`; an app backend that needs a trusted identity
   * must not accept one the frontend merely relays. Ask per use rather
   * than caching across a session — the viewer can change (#2805).
   */
  function getViewer(options) {
    return request('getViewer', undefined, options)
      .then((payload) => {
        const viewer = payload && payload.viewer;
        return viewer && typeof viewer.id === 'string' && viewer.id && typeof viewer.name === 'string'
          ? { id: viewer.id, name: viewer.name }
          : null;
      })
      .catch(() => null);
  }

  return {
    createChat,
    init,
    sendToChat,
    suggest,
    notifyContext,
    publishArtifact,
    navIntent,
    getAppPortalToken,
    getViewer,
    onCommand,
    request,
    destroy,
  };
}

export const praetor = createBridge();
export const { init, sendToChat, suggest, notifyContext, publishArtifact, navIntent, getAppPortalToken, getViewer, onCommand, request, destroy } = praetor;
export default praetor;
